  "source": {
    "question": "Help me see a redundant constraint graphically: maximize Z = 2x + y with x >= 0, y >= 0, x + y <= 5 and 2x + 2y <= 12. Show which boundary actually limits the region."
  },
  "quantities": [
    {"id": "g1", "symbol": "b_1", "value": 5},
    {"id": "g2", "symbol": "b_2", "value": 12}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "x and y coordinate axes"},
    {"id": "feasible", "kind": "linear_region", "role": "feasible region with both constraint boundaries"}
  ],
  "constructions": [
    {
      "id": "makeAxes",
      "operator": "axes",
      "inputs": {"xMin": -0.5, "xMax": 7, "yMin": -0.5, "yMax": 7},
      "outputs": ["axes"]
    },
    {
      "id": "makeFeasible",
      "operator": "linear_feasible_region",
      "inputs": {
        "variables": ["x", "y"],
        "constraints": ["x>=0", "y>=0", "x+y<=5", "2*x+2*y<=12"],
        "objective": {"expression": "2*x+y", "sense": "max"}
      },
      "outputs": ["feasible"]
    }
  ],
  "relations": [],
  "assertions": [],
  "annotations": [],
  "requiredEntityIds": ["axes", "feasible"],
  "revealGroups": [
    {
      "id": "setup",
      "entityIds": ["axes", "feasible"],
      "dependsOn": [],
      "narrationCue": "The shaded first-quadrant region stops at x + y = 5. The boundary 2x + 2y = 12 lies farther out and does not limit it."
    }
  ],
  "teachingTimeline": []
}

{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The given linear constraints define an exact feasible region and two comparable boundaries."
  },
  "source": {
    "question": "Help me see a redundant constraint graphically: maximize Z = 2x + y with x >= 0, y >= 0, x + y <= 5 and 2x + 2y <= 12. Show which boundary actually limits the region."
  },
  "quantities": [
    {"id": "g1", "symbol": "b_1", "value": 5, "provenance": "given"},
    {"id": "g2", "symbol": "b_2", "value": 12, "provenance": "given"},
    {"id": "d1", "symbol": "b_2/2", "value": 6, "provenance": "derived", "dependsOn": ["g2"]},
    {"id": "u1", "symbol": "x*", "value": 5, "provenance": "derived", "dependsOn": ["g1", "d1"]},
    {"id": "u2", "symbol": "y*", "value": 0, "provenance": "derived", "dependsOn": ["g1", "d1"]},
    {"id": "u3", "symbol": "Z_max", "value": 10, "provenance": "derived", "dependsOn": ["u1", "u2"]}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "x and y axes"},
    {"id": "feasible", "kind": "linear_region", "role": "feasible region"},
    {"id": "limiting", "kind": "polyline", "role": "boundary x + y = 5", "label": "x + y = 5"},
    {"id": "redundant", "kind": "polyline", "role": "boundary 2x + 2y = 12", "label": "2x + 2y = 12"},
    {"id": "optimum", "kind": "point", "role": "maximizing feasible vertex", "label": "(5,0)"}
  ],
  "constructions": [
    {"id": "make_axes", "operator": "axes", "inputs": {"xMin": -0.5, "xMax": 7, "yMin": -0.5, "yMax": 7}, "outputs": ["axes"]},
    {"id": "make_feasible", "operator": "linear_feasible_region", "inputs": {"variables": ["x", "y"], "constraints": ["x >= 0", "y >= 0", "x + y <= 5", "2x + 2y <= 12"], "objective": {"expression": "2x + y", "sense": "max"}}, "outputs": ["feasible"]},
    {"id": "make_limiting", "operator": "function_curve", "inputs": {"expression": "5-x", "xMin": 0, "xMax": 5}, "outputs": ["limiting"]},
    {"id": "make_redundant", "operator": "function_curve", "inputs": {"expression": "6-x", "xMin": 0, "xMax": 6}, "outputs": ["redundant"]},
    {"id": "make_optimum", "operator": "curve_anchor", "inputs": {"curve": "limiting", "at": 5}, "outputs": ["optimum"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "optimum_on_boundary", "predicate": "function_value", "entities": ["limiting"], "expected": {"x": 5, "y": 0}, "severity": "fatal"}
  ],
  "annotations": [
    {"id": "limiting_note", "kind": "callout", "targetIds": ["limiting", "feasible"], "text": "This boundary limits the shaded region."},
    {"id": "redundant_note", "kind": "callout", "targetIds": ["redundant"], "text": "Dividing its constraint by 2 gives x + y ≤ 6. It lies outside the feasible region.", "quantityId": "d1"},
    {"id": "maximum_note", "kind": "callout", "targetIds": ["optimum"], "text": "Z_max = 10", "quantityId": "u3"}
  ],
  "requiredEntityIds": ["axes", "feasible", "limiting", "redundant", "optimum"],
  "revealGroups": [
    {"id": "setup", "entityIds": ["axes", "feasible", "limiting"], "dependsOn": []},
    {"id": "comparison", "entityIds": ["redundant"], "dependsOn": ["setup"]},
    {"id": "result", "entityIds": ["optimum"], "dependsOn": ["comparison"]}
  ],
  "teachingTimeline": [
    {"id": "show_setup", "revealGroupId": "setup", "narration": "Shade the points satisfying all four constraints. The x + y = 5 boundary meets the shaded region."},
    {"id": "show_comparison", "revealGroupId": "comparison", "narration": "The other boundary is x + y = 6, parallel to and farther from the origin than x + y = 5. Its constraint is redundant."},
    {"id": "show_result", "revealGroupId": "result", "narration": "After identifying the feasible region, evaluate the objective at its vertices. The maximum is 10 at (5,0)."}
  ]
}

